names-grouped-totals.good:
public async Task<List<(int BlogId, int TotalViews)>> TotalViewsPerBlog(BlogContext blogContext, string searchTerm)
{
    var totalsQuery = from post in blogContext.Posts where post.Title.Contains(searchTerm) group post by post.BlogId into blogPosts select new { BlogId = blogPosts.Key, TotalViews = blogPosts.Sum(blogPost => blogPost.Views) };
    var totals = await totalsQuery.ToListAsync();
    return totals.Select(total => (total.BlogId, total.TotalViews)).ToList();
}

